python3 << 'EOF'
import json

# Final validation
with open('/app/output/solution.json', 'r', encoding='utf-8') as f:
    data = json.load(f)

print("FINAL VALIDATION CHECKS\n" + "="*60)

# Check 1: All records have consistent structure
print("\n1. Structure Consistency")
errors = []
for record in data['records']:
    if not all(k in record for k in ['record_id', 'product_id', 'station', 'engineer_id', 'raw_reason_text', 'normalized']):
        errors.append(f"Missing field in {record['record_id']}")

    for segment in record['normalized']:
        if not all(k in segment for k in ['segment_id', 'span_text', 'pred_code', 'pred_label', 'confidence', 'rationale']):
            errors.append(f"Missing field in segment {segment.get('segment_id')}")

if errors:
    print(f"✗ Found {len(errors)} structural errors")
    for e in errors[:5]:
        print(f"  - {e}")
else:
    print("✓ All records have consistent structure")

# Check 2: Segment IDs are properly formatted
print("\n2. Segment ID Format")
segment_id_errors = 0
for record in data['records']:
    expected_segment_count = 1
    for segment in record['normalized']:
        sid = segment['segment_id']
        expected_prefix = f"{record['record_id']}-S"
        if not sid.startswith(expected_prefix):
            segment_id_errors += 1
            if segment_id_errors <= 3:
                print(f"  ✗ {sid} (expected prefix: {expected_prefix})")

if segment_id_errors == 0:
    print("✓ All segment IDs are properly formatted")
else:
    print(f"✗ Found {segment_id_errors} segment ID format errors")

# Check 3: Confidence values are valid
print("\n3. Confidence Value Validity")
conf_errors = 0
for record in data['records']:
    for segment in record['normalized']:
        conf = segment['confidence']
        if not isinstance(conf, (int, float)) or conf < 0 or conf > 1:
            conf_errors += 1
            if conf_errors <= 3:
                print(f"  ✗ {segment['segment_id']}: {conf}")

if conf_errors == 0:
    print("✓ All confidence values are valid (0.0-1.0)")
else:
    print(f"✗ Found {conf_errors} invalid confidence values")

# Check 4: Code format validation
print("\n4. Code Format Validation")
code_errors = 0
for record in data['records']:
    prod = record['product_id']
    for segment in record['normalized']:
        code = segment['pred_code']
        if code != 'UNKNOWN':
            # Valid code should start with product_id
            if not code.startswith(prod):
                code_errors += 1
                if code_errors <= 3:
                    print(f"  ✗ {code} in {prod}")

if code_errors == 0:
    print("✓ All codes match their product_id or are UNKNOWN")
else:
    print(f"⚠ Found {code_errors} code mismatches (may be acceptable)")

# Check 5: Span text must be from raw_reason_text
print("\n5. Span Text Verification")
span_errors = 0
for record in data['records']:
    raw = record['raw_reason_text']
    for segment in record['normalized']:
        span = segment['span_text']
        if span not in raw:
            span_errors += 1
            if span_errors <= 3:
                print(f"  ✗ '{span}' not in raw text of {record['record_id']}")

if span_errors == 0:
    print("✓ All span texts are extracted from raw_reason_text")
else:
    print(f"✗ Found {span_errors} span text mismatches")

# Check 6: UNKNOWN code has empty label
print("\n6. UNKNOWN Code Validation")
unknown_errors = 0
for record in data['records']:
    for segment in record['normalized']:
        if segment['pred_code'] == 'UNKNOWN' and segment['pred_label'] != '':
            unknown_errors += 1
        if segment['pred_code'] == 'UNKNOWN' and segment['confidence'] != 0.0:
            unknown_errors += 1

if unknown_errors == 0:
    print("✓ All UNKNOWN codes have empty label and 0.0 confidence")
else:
    print(f"✗ Found {unknown_errors} UNKNOWN code inconsistencies")

# Check 7: Known codes have non-empty labels
print("\n7. Known Code Label Validation")
label_errors = 0
for record in data['records']:
    for segment in record['normalized']:
        if segment['pred_code'] != 'UNKNOWN' and segment['pred_label'] == '':
            label_errors += 1

if label_errors == 0:
    print("✓ All known codes have non-empty labels")
else:
    print(f"✗ Found {label_errors} missing labels on known codes")

print("\n" + "="*60)
print("VALIDATION COMPLETE - Solution is ready for use")

EOF
